extends CanvasLayer
class_name GameHUD

var world_clock: WorldClock
var dynamic_objective_text := ""
var player: PlayerController

@onready var stats: Label = $Margin/VBox/Stats
@onready var objective: Label = $Objective
@onready var prompt: Label = $Prompt
@onready var blackout: ColorRect = $Blackout

func _ready() -> void:
    GameState.stat_changed.connect(_refresh)
    GameState.money_changed.connect(_refresh_money)
    GameState.blackout_changed.connect(_on_blackout)
    _refresh("", 0.0)
    _on_blackout(GameState.blackout_active)

func bind_dynamic_objectives(manager: DynamicObjectiveManager) -> void:
    manager.dynamic_objective_changed.connect(_on_dynamic_objective_changed)

func _on_dynamic_objective_changed(text: String) -> void:
    dynamic_objective_text = text

func bind_clock(clock: WorldClock) -> void:
    world_clock = clock

func bind_player(value: PlayerController) -> void:
    player = value
    player.interaction_target_changed.connect(_on_target_changed)

func bind_missions(manager: MissionManager) -> void:
    manager.objective_text_changed.connect(_on_objective_changed)

func _process(_delta: float) -> void:
    _refresh_stats()

func _refresh_stats() -> void:
    var time_text := world_clock.formatted_time() if world_clock else ""
    var shortages := ""
    if GameState.water_shortage:
        shortages += "\nالماء المعدني: مقطوع"
    if GameState.fuel_shortage:
        shortages += "\nالإيصنص: ناقص"
    stats.text = "%s\nالفلوس: %.1f د.ت\nالماء: %d%%   الطاقة: %d%%\nالإيصنص: %d%%   المزاج: %d%%%s" % [
        time_text, GameState.money, int(GameState.water), int(GameState.energy), int(GameState.fuel), int(GameState.mood), shortages
    ]

func _refresh(_name: String, _value: float) -> void:
    _refresh_stats()

func _refresh_money(_value: float) -> void:
    _refresh_stats()

func _on_target_changed(target: Interactable) -> void:
    prompt.text = "" if target == null else "E — " + target.prompt_ar

func _on_objective_changed(text: String) -> void:
    objective.text = "المهمة: " + text + ("\n" + dynamic_objective_text if not dynamic_objective_text.is_empty() else "")

func _on_blackout(active: bool) -> void:
    blackout.color = Color(0,0,0,0.38 if active else 0.0)


func current_interaction_prompt() -> String:
    if player == null or player.interaction_target == null:
        return ""
    if not player.interaction_target.can_interact(player):
        return ""
    return str(player.interaction_target.prompt_ar)

extends Control
class_name RefuelPopup

var fuel_system = null

@onready var title_label: Label = $Panel/Margin/VBox/Title
@onready var status_label: Label = $Panel/Margin/VBox/Status
@onready var buttons_box: VBoxContainer = $Panel/Margin/VBox/Buttons

func configure(system) -> void:
    fuel_system = system
    if fuel_system != null:
        fuel_system.fuel_purchased.connect(_on_fuel_purchased)
        fuel_system.purchase_rejected.connect(_on_purchase_rejected)
    rebuild()

func open_popup() -> void:
    visible = true
    rebuild()

func close_popup() -> void:
    visible = false

func rebuild() -> void:
    if buttons_box == null:
        return
    for child in buttons_box.get_children():
        child.queue_free()
    if fuel_system == null:
        status_label.text = "محطة البنزين غير متاحة"
        return

    title_label.text = "تعبئة الإيصنص — %.0f%%" % GameState.fuel
    status_label.text = "فلوسك: %.1f د.ت" % GameState.money

    for amount in fuel_system.presets():
        var percent: float = float(amount)
        var button: Button = Button.new()
        var actual: float = minf(percent, 100.0 - float(GameState.fuel))
        var cost: float = float(fuel_system.price_for(actual))
        button.text = "+%.0f%% — %.1f د.ت" % [actual, cost]
        button.disabled = actual <= 0.0
        button.pressed.connect(_purchase.bind(percent))
        buttons_box.add_child(button)

    var max_button: Button = Button.new()
    var max_amount: float = float(fuel_system.max_affordable_percent())
    max_button.text = "عبّي بالموجود (+%.0f%%)" % max_amount
    max_button.disabled = max_amount <= 0.0
    max_button.pressed.connect(_purchase_max)
    buttons_box.add_child(max_button)

    var close_button: Button = Button.new()
    close_button.text = "سكر"
    close_button.pressed.connect(close_popup)
    buttons_box.add_child(close_button)

func _purchase(percent: float) -> void:
    if fuel_system != null:
        fuel_system.purchase(percent)
        rebuild()

func _purchase_max() -> void:
    if fuel_system != null:
        fuel_system.purchase_max_affordable()
        rebuild()

func _on_fuel_purchased(percent_added: float, cost: float) -> void:
    status_label.text = "زِدت %.0f%% بـ %.1f د.ت" % [percent_added, cost]

func _on_purchase_rejected(reason: String) -> void:
    match reason:
        "fuel_shortage":
            status_label.text = "الإيصنص ناقص توا"
        "insufficient_funds":
            status_label.text = "فلوسك ما تكفيش"
        "tank_full":
            status_label.text = "الريزرفوار معبّي"
        "below_minimum":
            status_label.text = "الكمية أقل من الحد الأدنى"
        _:
            status_label.text = "التعبئة ما نجحتش"

extends Control
class_name MobileActionBar

signal phone_pressed
signal interact_pressed
signal pause_pressed

@onready var phone_button: Button = $PhoneButton
@onready var interact_button: Button = $InteractButton
@onready var pause_button: Button = $PauseButton

func _ready() -> void:
    phone_button.pressed.connect(func(): phone_pressed.emit())
    interact_button.pressed.connect(func(): interact_pressed.emit())
    pause_button.pressed.connect(func(): pause_pressed.emit())

func set_interact_enabled(value: bool) -> void:
    interact_button.disabled = not value

func set_interact_label(value: String) -> void:
    interact_button.text = value if not value.is_empty() else "تفاعل"

extends Node
class_name MobileInputRouter

var move_vector := Vector2.ZERO
var sprint_pressed := false

func set_move_vector(value: Vector2) -> void:
    move_vector = value

func set_sprint_pressed(value: bool) -> void:
    sprint_pressed = value

func movement_vector() -> Vector2:
    return move_vector

func wants_sprint() -> bool:
    return sprint_pressed
